function esc(value) { return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char])); }
function money(job) { const amount = Number(job.amountValue || String(job.bidAmount || "").replace(/[$,]/g, "")); return Number.isFinite(amount) && amount > 0 ? new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(amount) : (job.bidAmount || "Not listed"); }
function status(job) { return String(job.status || "Open"); }
function mapsHref(latitude, longitude, address) { const query = latitude && longitude ? `${latitude},${longitude}` : address; return query ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}` : ""; }
